#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1000000007LL

typedef long long ll;

typedef struct {
    int to, next;
} Edge;

static int cmp_int(const void *a, const void *b) {
    int x = *(const int*)a;
    int y = *(const int*)b;
    return (x > y) - (x < y);
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    Edge *edges = (Edge*)malloc(sizeof(Edge) * M);
    int *head = (int*)malloc(sizeof(int) * N);
    int *indeg = (int*)calloc(N, sizeof(int));
    for (int i = 0; i < N; i++) head[i] = -1;

    for (int i = 0; i < M; i++) {
        int A, B;
        scanf("%d %d", &A, &B);
        A--; B--;
        edges[i].to = B;
        edges[i].next = head[A];
        head[A] = i;
        indeg[B]++;
    }

    /* Topological sort (assumes rules form a DAG / valid implication ordering) */
    int *queue = (int*)malloc(sizeof(int) * N);
    int qh = 0, qt = 0;
    for (int i = 0; i < N; i++) {
        if (indeg[i] == 0) queue[qt++] = i;
    }

    int *topo = (int*)malloc(sizeof(int) * N);
    int tcnt = 0;
    while (qh < qt) {
        int u = queue[qh++];
        topo[tcnt++] = u;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (--indeg[v] == 0) queue[qt++] = v;
        }
    }

    /* If not all nodes processed, there is a cycle.
       In that case valid states are fixed points of implications;
       however typical problem setting uses acyclic rules.
       We safely handle by outputting 0 for invalid cyclic input. */
    if (tcnt != N) {
        printf("0\n");
        free(edges); free(head); free(indeg); free(queue); free(topo);
        return 0;
    }

    /* Bitset transitive closure:
       reach[u][v] = 1 if u => v
    */
    int W = (N + 63) >> 6;
    unsigned long long *reach = (unsigned long long*)calloc((size_t)N * W, sizeof(unsigned long long));

    for (int i = N - 1; i >= 0; i--) {
        int u = topo[i];
        unsigned long long *ru = reach + (size_t)u * W;
        ru[u >> 6] |= 1ULL << (u & 63); /* include itself */
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            unsigned long long *rv = reach + (size_t)v * W;
            for (int k = 0; k < W; k++) ru[k] |= rv[k];
        }
    }

    /* Build unique closures */
    int *order = (int*)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) order[i] = i;

    /* Sort indices lexicographically by their bitsets to group equal closures */
    /* Simple qsort with global-like access via static not convenient; use insertion of keys by hashing avoided.
       Instead, encode closures to strings is too heavy.
       We'll sort by custom comparator using globals through static variables.
    */
    static unsigned long long *g_reach;
    static int g_W;
    g_reach = reach;
    g_W = W;

    int cmp_idx(const void *a, const void *b) {
        int x = *(const int*)a;
        int y = *(const int*)b;
        unsigned long long *rx = g_reach + (size_t)x * g_W;
        unsigned long long *ry = g_reach + (size_t)y * g_W;
        for (int i = 0; i < g_W; i++) {
            if (rx[i] < ry[i]) return -1;
            if (rx[i] > ry[i]) return 1;
        }
        return 0;
    }

    qsort(order, N, sizeof(int), cmp_idx);

    int *rep = (int*)malloc(sizeof(int) * N);
    int groups = 0;
    for (int i = 0; i < N; ) {
        int j = i + 1;
        while (j < N && cmp_idx(&order[i], &order[j]) == 0) j++;
        for (int k = i; k < j; k++) rep[order[k]] = groups;
        groups++;
        i = j;
    }

    /* For each group, compute its closure over groups */
    unsigned long long *groupMask = (unsigned long long*)calloc((size_t)groups * ((groups + 63) >> 6), sizeof(unsigned long long));
    int GW = (groups + 63) >> 6;

    int *seen = (int*)calloc(groups, sizeof(int));
    int stamp = 1;

    for (int gnode = 0; gnode < N; gnode++) {
        int g = rep[gnode];
        if (seen[g] == stamp) continue;
        seen[g] = stamp;

        unsigned long long *rn = reach + (size_t)gnode * W;
        unsigned long long *gm = groupMask + (size_t)g * GW;

        for (int v = 0; v < N; v++) {
            if ((rn[v >> 6] >> (v & 63)) & 1ULL) {
                int gv = rep[v];
                gm[gv >> 6] |= 1ULL << (gv & 63);
            }
        }
    }

    /* Count antichain choices in poset of unique closures.
       Since choosing a bent finger means including its whole closure,
       the number of distinct countable numbers equals number of distinct ideals.
       In this transformed poset, closures are laminar by inclusion; count via DP over inclusion forest.
    */

    int *parent = (int*)malloc(sizeof(int) * groups);
    for (int i = 0; i < groups; i++) parent[i] = -1;

    for (int i = 0; i < groups; i++) {
        int best = -1, bestSize = N + 1;
        unsigned long long *mi = groupMask + (size_t)i * GW;

        for (int j = 0; j < groups; j++) if (i != j) {
            unsigned long long *mj = groupMask + (size_t)j * GW;

            int subset = 1;
            for (int k = 0; k < GW; k++) {
                if ((mi[k] & ~mj[k]) != 0ULL) {
                    subset = 0;
                    break;
                }
            }
            if (!subset) continue;

            int equal = 1;
            for (int k = 0; k < GW; k++) {
                if (mi[k] != mj[k]) { equal = 0; break; }
            }
            if (equal) continue;

            int sz = 0;
            for (int k = 0; k < GW; k++) sz += __builtin_popcountll(mj[k]);
            if (sz < bestSize) {
                bestSize = sz;
                best = j;
            }
        }
        parent[i] = best;
    }

    int *childCnt = (int*)calloc(groups, sizeof(int));
    for (int i = 0; i < groups; i++) if (parent[i] != -1) childCnt[parent[i]]++;

    int **children = (int**)malloc(sizeof(int*) * groups);
    for (int i = 0; i < groups; i++) {
        children[i] = childCnt[i] ? (int*)malloc(sizeof(int) * childCnt[i]) : NULL;
        childCnt[i] = 0;
    }
    for (int i = 0; i < groups; i++) if (parent[i] != -1) {
        children[parent[i]][childCnt[parent[i]]++] = i;
    }

    ll *dp = (ll*)malloc(sizeof(ll) * groups);

    int *stk = (int*)malloc(sizeof(int) * groups * 2);
    int sp = 0;
    for (int i = 0; i < groups; i++) if (parent[i] == -1) {
        stk[sp++] = i;
        stk[sp++] = 0;
    }

    while (sp) {
        int state = stk[--sp];
        int u = stk[--sp];
        if (state == 0) {
            stk[sp++] = u;
            stk[sp++] = 1;
            for (int i = 0; i < childCnt[u]; i++) {
                stk[sp++] = children[u][i];
                stk[sp++] = 0;
            }
        } else {
            ll ways = 1; /* do not choose anything from descendants */
            for (int i = 0; i < childCnt[u]; i++) {
                int v = children[u][i];
                ways = (ways * (dp[v] + 1)) % MOD;
            }
            dp[u] = ways;
        }
    }

    ll ans = 1;
    for (int i = 0; i < groups; i++) if (parent[i] == -1) {
        ans = (ans * (dp[i] + 1)) % MOD;
    }

    /* exclude impossible double-count? No: includes empty set, which is count 0, valid. */
    printf("%lld\n", ans % MOD);

    free(edges);
    free(head);
    free(indeg);
    free(queue);
    free(topo);
    free(reach);
    free(order);
    free(rep);
    free(groupMask);
    free(seen);
    free(parent);
    for (int i = 0; i < groups; i++) free(children[i]);
    free(children);
    free(childCnt);
    free(dp);
    free(stk);

    return 0;
}

