        for (int to : g[v]) {
            if (!vis[to]) dfs1(to);
        }
        order.push_back(v);
    };

    for (int i = 0; i < N; ++i) {
        if (!vis[i]) dfs1(i);
    }

    // Second pass: SCC ids
    vector<int> comp(N, -1);
    int sccCnt = 0;
    function<void(int)> dfs2 = [&](int v) {
        comp[v] = sccCnt;
        for (int to : rg[v]) {
            if (comp[to] == -1) dfs2(to);
        }
    };

    reverse(order.begin(), order.end());
    for (int v : order) {
        if (comp[v] == -1) {
            dfs2(v);
            ++sccCnt;
        }
    }

    // Build SCC DAG
    vector<vector<int>> dag(sccCnt);
    vector<int> indeg(sccCnt, 0);
    set<pair<int,int>> edges;
    for (int v = 0; v < N; ++v) {
        for (int to : g[v]) {
            int a = comp[v], b = comp[to];
            if (a != b && !edges.count({a, b})) {
                edges.insert({a, b});
                dag[a].push_back(b);
                indeg[b]++;
            }
        }
    }

    // Count source SCCs in condensation DAG
    int sources = 0;
    for (int i = 0; i < sccCnt; ++i) {
        if (indeg[i] == 0) sources++;
    }

    // Number of valid bend configurations = 2^(number of source SCCs)
    long long ans = 1;
    long long base = 2;
    int exp = sources;
    while (exp > 0) {
        if (exp & 1) ans = (ans * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }

    cout << ans % MOD << '\n';
    return 0;
}

