            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            g[a].add(b);
            rg[b].add(a);
        }

        // Kosaraju: first pass order
        boolean[] vis = new boolean[N];
        ArrayList<Integer> order = new ArrayList<>(N);
        for (int i = 0; i < N; i++) {
            if (!vis[i]) dfs1Iterative(i, g, vis, order);
