        int[] comp = new int[N];
        Arrays.fill(comp, -1);
        int compCnt = 0;
        for (int i = order.size() - 1; i >= 0; i--) {
            int v = order.get(i);
            if (comp[v] == -1) {
                dfs2Iterative(v, rg, comp, compCnt);
                compCnt++;
            }
        }

