    }

    static long modPow(long a, long e, long mod) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = (r * a) % mod;
            a = (a * a) % mod;
            e >>= 1;
        }
        return r;
    }

    static void dfs1Iterative(int start, List<Integer>[] g, boolean[] vis, List<Integer> order) {
        ArrayDeque<int[]> st = new ArrayDeque<>();
        st.push(new int[]{start, 0});
        vis[start] = true;

        while (!st.isEmpty()) {
            int[] top = st.peek();
            int v = top[0];
            int idx = top[1];

            if (idx < g[v].size()) {
                int to = g[v].get(idx);
                top[1]++;
                if (!vis[to]) {
                    vis[to] = true;
                    st.push(new int[]{to, 0});
                }
            } else {
                st.pop();
                order.add(v);
            }
        }
    }

    static void dfs2Iterative(int start, List<Integer>[] rg, int[] comp, int cid) {
        ArrayDeque<Integer> st = new ArrayDeque<>();
        st.push(start);
        comp[start] = cid;

        while (!st.isEmpty()) {
            int v = st.pop();
            for (int to : rg[v]) {
                if (comp[to] == -1) {
                    comp[to] = cid;
                    st.push(to);
                }
            }
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

import sys
sys.setrecursionlimit(300000)
MOD = 1000000007

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    M = int(next(it))
    g = [[] for _ in range(N)]
    gr = [[] for _ in range(N)]
    for _ in range(M):
        a = int(next(it)) - 1
        b = int(next(it)) - 1
        g[a].append(b)
        gr[b].append(a)

    # Kosaraju
    visited = [False]*N
    order = []
    def dfs1(u):
        visited[u] = True
        for v in g[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)
    for i in range(N):
        if not visited[i]:
            dfs1(i)

    comp = [-1]*N
    def dfs2(u, cid):
        comp[u] = cid
        for v in gr[u]:
            if comp[v] == -1:
                dfs2(v, cid)
    cid = 0
    for u in reversed(order):
        if comp[u] == -1:
            dfs2(u, cid)
            cid += 1

    # Build condensed DAG
    C = cid
    dag = [set() for _ in range(C)]
    indeg = [0]*C
    for u in range(N):
        for v in g[u]:
            cu, cv = comp[u], comp[v]
            if cu != cv and cv not in dag[cu]:
                dag[cu].add(cv)
                indeg[cv] += 1

    # Topological order
    from collections import deque
    q = deque([i for i in range(C) if indeg[i] == 0])
    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in dag[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    dp = [1]*C
    for u in reversed(topo):
        prod = 1
        for v in dag[u]:
            prod = (prod * dp[v]) % MOD
        dp[u] = (1 + prod) % MOD

    ans = 1
    for u in range(C):
        if indeg[u] == 0:  # actually indeg was modified; recompute indeg
            pass
    # recompute indeg properly
    indeg2 = [0]*C
    for u in range(C):
        for v in dag[u]:
            indeg2[v] += 1
    ans = 1
    for u in range(C):
        if indeg2[u] == 0:
            ans = (ans * dp[u]) % MOD
    print(ans)

if __name__ == "__main__":
    solve()
